def react_loop(gen, tools, max_steps=8, max_repeat=2):
    history = []
    seen = {}
    for _ in range(max_steps):
        action, arg = gen(history)
        if action == 'finish':
            return arg
        key = (action, str(arg))
        seen[key] = seen.get(key, 0) + 1
        if seen[key] > max_repeat:
            return '熔断: 重复动作 %s' % (key,)
        obs = tools[action](arg) if action in tools else 'UNKNOWN_TOOL'
        history.append((action, arg, obs))
    return '熔断: 超出步数上限'


