import zlib


def detect_cycle(messages, max_repeat=2):
    seen = {}
    for i, (a, b, content) in enumerate(messages, start=1):
        fingerprint = zlib.crc32(content.encode('utf-8'))
        signature = (a, b, fingerprint)
        seen[signature] = seen.get(signature, 0) + 1
        if seen[signature] > max_repeat:
            return i
    return None


